import { Module } from './module/module'; // eslint-disable-next-line import/no-default-export

export default class _class extends Module {
  initialize() {
    this.listeners.add(this.adminButtonEl, 'click', e => {
      const adminIsOpen = this.adminSectionEl.classList.contains(this.activeClass);
      this.adminSectionEl.classList.toggle(this.activeClass, !adminIsOpen);

      if (window.BAO.mediaBreakpoints.isMd && adminIsOpen === false) {
        this.adminInputEl.focus();
      }
    });
  }

  get activeClass() {
    return this.data.get('activeClass');
  }

}
_class.targets = ['adminSection', 'adminButton', 'adminInput'];